import { useCallback, useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultDate?: Date;
  onChange?: (date: Date) => void;
};

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (date: Date, days: number): Date => {
  const next = startOfDay(date);
  next.setDate(next.getDate() + days);
  return next;
};

const isSameDay = (a: Date, b: Date): boolean =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

const PRESETS: ReadonlyArray<{ label: string; offset: number }> = [
  { label: 'Сегодня', offset: 0 },
  { label: 'Вчера', offset: -1 },
  { label: 'Неделя назад', offset: -7 },
];

export default function ReportDatePicker({ defaultDate, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date>(() => startOfDay(defaultDate ?? new Date()));

  const commit = useCallback(
    (next: Date) => {
      const normalized = startOfDay(next);
      setValue(normalized);
      onChange?.(normalized);
    },
    [onChange],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-3, 12px)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
      >
        {PRESETS.map((preset) => {
          const presetDate = shiftDays(new Date(), preset.offset);
          const active = isSameDay(presetDate, value);
          return (
            <JxButton
              key={preset.label}
              type="button"
              size="sm"
              variant={active ? 'primary' : 'secondary'}
              aria-pressed={active}
              onClick={() => commit(presetDate)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar
        aria-label="Дата отчёта"
        value={value}
        onValueChange={(next: Date | null) => {
          if (next) commit(next);
        }}
      />
    </div>
  );
}

